import { MeshStandardNodeMaterial } from 'three/webgpu';
import {
  uv,
  mix,
  color,
  smoothstep,
  texture,
  vec4,
  clamp,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, Mesh, DirectionalLight, DoubleSide } = THREE;

  const PALETTE = config?.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'pricing-card-1-label';

  // ---- geometry / material (engineered gradient surface) ----------------
  const WIDTH = 1.7;
  const HEIGHT = 0.52;
  const geometry = new PlaneGeometry(WIDTH, HEIGHT, 1, 1);

  const material = new MeshStandardNodeMaterial({
    side: DoubleSide,
    roughness: 0.55,
    metalness: 0.32,
    clearcoat: 0.15,
  });

  const inkColor = color(PALETTE.ink);
  const surfaceColor = color(PALETTE.surface);
  const accentColor = color(PALETTE.accent);

  let texNode = null;

  function buildColorNode() {
    const uvNode = uv();
    // engineered vertical gradient: surface (bottom) -> ink (top)
    let grad = mix(surfaceColor, inkColor, uvNode.y);

    // thin accent underline stripe (label baseline mark), <=10% of frame
    const stripe = smoothstep(0.0, 0.03, uvNode.y).oneMinus().mul(
      smoothstep(0.0, 0.06, uvNode.y)
    );
    grad = mix(grad, accentColor, clamp(stripe, 0.0, 1.0).mul(0.9));

    if (texNode) {
      const decor = texNode.sample(uvNode);
      // subtle decorative orb overlay, kept low-key so it never competes
      // with the headline (single brightest element rule)
      grad = mix(grad, decor.rgb, decor.a.mul(0.18));
    }
    return vec4(grad, 1.0);
  }

  material.colorNode = buildColorNode();

  const mesh = new Mesh(geometry, material);
  mesh.name = 'label-surface';
  group.add(mesh);

  // ---- node-local rim light (accent-hued, capped intensity) -------------
  const rim = new DirectionalLight(PALETTE.accent, 0.5);
  rim.position.set(-0.6, 0.4, 0.8);
  group.add(rim);

  // ---- headline text: "Pricing 1" ----------------------------------------
  const items =
    config.textContent ?? config?.intent?.visualSpec?.textContent ?? [];

  const textNodes = [];
  for (const item of items) {
    const fontSize = item?.typography?.fontSize ?? 39;
    const txt = ctx.fontAtlas.createText(item.text ?? 'Pricing 1', {
      fontSize,
      color: PALETTE.paper,
      align: 'center',
    });
    txt.position.set(0, 0, 0.03);
    group.add(txt);
    textNodes.push(txt);
  }

  // ---- decorative texture (orb-decor.png) --------------------------------
  let loadedTexture = null;
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      loadedTexture = tex;
      texNode = texture(tex);
      material.colorNode = buildColorNode();
      material.needsUpdate = true;
    });
  }

  // ---- entrance motion: weighted-settle / rise-in (static after) --------
  group.position.y -= 0.0; // scenePosition applied by adapter; local offset only
  group.scale.setScalar(0.97);
  const startY = 0.4;
  group.userData._introOffset = startY;
  mesh.position.y = 0;

  const tl = gsap.timeline();
  tl.fromTo(
    group.position,
    { y: `+=${startY}` },
    { y: `-=${startY}`, duration: 0.7, ease: 'power3.out' },
    0
  );
  tl.fromTo(
    group.scale,
    { x: 0.97, y: 0.97, z: 0.97 },
    { x: 1.04, y: 1.04, z: 1.04, duration: 0.55, ease: 'power2.out' },
    0
  );
  tl.to(
    group.scale,
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.35, ease: 'power4.out' },
    0.55
  );

  // ---- primitives (none specified for this node) -------------------------
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const handle = ctx.primitives[prim.name]?.(group, prim.params);
    if (handle) primitiveHandles.push(handle);
  }

  // ---- no interactions for this static label -----------------------------
  group.userData.handlers = {};

  group.userData.cleanup = function cleanup() {
    tl.kill();
    for (const h of primitiveHandles) {
      h?.cleanup?.();
    }
    for (const t of textNodes) {
      t.parent?.remove(t);
      t.geometry?.dispose?.();
      t.material?.dispose?.();
    }
    geometry.dispose();
    material.dispose();
    if (loadedTexture) {
      loadedTexture.dispose();
    }
    rim.dispose?.();
    group.clear();
  };

  return group;
}
